-- Apply after 048. Add business questions without changing existing required fields, permissions or outcomes.
BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
DO $fields$
DECLARE item jsonb; question jsonb; existing jsonb;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements($metadata$[{"code":"buy-sell","fields":[{"key":"listingKind","label":"What are you listing?","options":["Item for sale","Service","For rent"],"required":false},{"key":"rate","label":"Service or rental rate (PHP)","type":"number","required":false},{"key":"rateUnit","label":"Rate basis (per hour, day or service)","type":"text","required":false},{"key":"business","label":"Business or provider name","type":"text","required":false},{"key":"facebook","label":"Social page","type":"url","required":false}]},{"code":"businesses","fields":[{"key":"listedBy","label":"Listed by","type":"text","required":false},{"key":"facebook","label":"Business social page","type":"url","required":false}]},{"code":"jobs","fields":[{"key":"contact","label":"Contact details","type":"text","required":false}]},{"code":"workshops","fields":[{"key":"category","label":"Training category","type":"text","required":false},{"key":"contact","label":"Contact details","type":"text","required":false},{"key":"signupLink","label":"Registration or information link","type":"url","required":false}]},{"code":"booth-events","fields":[{"key":"theme","label":"Event theme","type":"text","required":false},{"key":"vendorRules","label":"Vendor rules","type":"textarea","required":false},{"key":"contact","label":"Event contact details","type":"text","required":false}]},{"code":"booth-applications","fields":[{"key":"vendor","label":"Vendor name","type":"text","required":false},{"key":"phone","label":"Vendor phone","type":"text","required":false}]},{"code":"guard-roster","fields":[{"key":"contact","label":"Guard contact number","type":"text","required":false},{"key":"shift","label":"Shift name","type":"text","required":false}]},{"code":"carpools","fields":[{"key":"kind","label":"I am","options":["Offering a ride","Looking for a ride"],"required":false},{"key":"contribution","label":"Proposed contribution per rider (PHP)","type":"number","required":false},{"key":"note","label":"Ride notes","type":"textarea","required":false}]},{"code":"ride-requests","fields":[{"key":"station","label":"Station or stop number","type":"text","required":false},{"key":"driverNote","label":"Note for the driver","type":"textarea","required":false}]},{"code":"board-reports","fields":[{"key":"reportedIncome","label":"Reported income (PHP)","type":"number","required":false},{"key":"reportedExpenses","label":"Reported expenses (PHP)","type":"number","required":false},{"key":"reportLink","label":"Full report link","type":"url","required":false},{"key":"reportDate","label":"Report date","type":"date","required":false}]},{"code":"election-candidates","fields":[{"key":"credentials","label":"Candidate credentials","type":"textarea","required":false}]}]$metadata$::jsonb) LOOP
  SELECT d.fields INTO existing FROM public.bfe_feature_definitions d WHERE d.code=item->>'code' FOR UPDATE;
  IF existing IS NULL THEN RAISE EXCEPTION 'Install feature definitions through 048 first.'; END IF;
  FOR question IN SELECT value FROM jsonb_array_elements(item->'fields') LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(existing) f WHERE f->>'key'=question->>'key') THEN existing:=existing||jsonb_build_array(question);
   ELSIF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(existing) f WHERE f->>'key'=question->>'key' AND f=question) THEN RAISE EXCEPTION 'Business field differs from the reviewed question. No changes applied.'; END IF;
  END LOOP;
  UPDATE public.bfe_feature_definitions SET fields=existing WHERE code=item->>'code';
 END LOOP;
END;$fields$;
NOTIFY pgrst,'reload schema'; COMMIT;
